const raw = $input.first().json.data;

const lines = raw.trim().split('\n');
const headers = lines[0].split(',');

// Valid LAD24CD prefixes only - excludes subtotal rows (E06, E07, E08, E09 without full code)
const validCode = /^E\d{8}$/;

const rows = [];

for (let i = 1; i < lines.length; i++) {
  // Handle quoted fields (source column contains commas)
  const cols = [];
  let current = '';
  let inQuotes = false;
  for (const ch of lines[i]) {
    if (ch === '"') { inQuotes = !inQuotes; }
    else if (ch === ',' && !inQuotes) { cols.push(current); current = ''; }
    else { current += ch; }
  }
  cols.push(current);

  const lad24cd = cols[0];
  if (!validCode.test(lad24cd)) continue;

  const missing = cols[3] === 'True';

  rows.push({
    lad24cd,
    la_name: cols[1],
    financial_year: cols[2],
    data_missing: missing,
    nightly_paid_ta_gross_exp_000:           missing ? null : parseFloat(cols[4]) || 0,
    nightly_paid_ta_net_exp_000:             missing ? null : parseFloat(cols[5]) || 0,
    hostels_gross_exp_000:                   missing ? null : parseFloat(cols[6]) || 0,
    hostels_net_exp_000:                     missing ? null : parseFloat(cols[7]) || 0,
    bb_gross_exp_000:                        missing ? null : parseFloat(cols[8]) || 0,
    bb_net_exp_000:                          missing ? null : parseFloat(cols[9]) || 0,
    hra_admin_prevention_relief_net_exp_000: missing ? null : parseFloat(cols[10]) || 0,
    total_homelessness_gross_exp_000:        missing ? null : parseFloat(cols[11]) || 0,
    total_homelessness_net_exp_000:          missing ? null : parseFloat(cols[12]) || 0,
    total_housing_gross_exp_000:             missing ? null : parseFloat(cols[13]) || 0,
    total_housing_net_exp_000:               missing ? null : parseFloat(cols[14]) || 0,
    source: cols.length > 15 ? cols[15] : cols[4]
  });
}

return [{ json: { rows, row_count: rows.length, batch_json: JSON.stringify(rows) } }];
